detaileddescription.para:
Usage example: //Loadanewsoundbufferfromafile
constsf::SoundBufferbuffer("sound.wav");

//Createasoundsourceboundtothebuffer
sf::Soundsound1(buffer);

//Playthesound
sound1.play();

//Createanothersoundsourceboundtothesamebuffer
sf::Soundsound2(buffer);

//Playitwithahigherpitch--thefirstsoundremainsunchanged
sound2.setPitch(2);
sound2.play();

//Loadsampleswithachannelmap
autosamples=std::vector<std::int16_t>();
//...
autochannelMap=std::vector<sf::SoundChannel>{
sf::SoundChannel::FrontLeft,
sf::SoundChannel::FrontCenter,
sf::SoundChannel::FrontRight,
sf::SoundChannel::BackRight,
sf::SoundChannel::BackLeft,
sf::SoundChannel::LowFrequencyEffects
};
autosoundBuffer=sf::SoundBuffer(samples.data(),samples.size(),channelMap.size(),44100,channelMap);
autosound=sf::Sound(soundBuffer);
